#include "SynthState.h"
#include "PresetLibrary.h"

#include "ExternalPresetImport.h"

using namespace juce;

namespace noctrl {

var PresetMetadata::toJson()const{auto obj=std::make_unique<DynamicObject>();obj->setProperty("name",name);obj->setProperty("author",author);obj->setProperty("category",category);obj->setProperty("description",description);obj->setProperty("notes",notes);obj->setProperty("tags",tags);obj->setProperty("rating",jlimit(0,5,rating));return var(obj.release());}

PresetMetadata PresetMetadata::fromJson(const var& v){PresetMetadata m;m.name=v.getProperty("name",{}).toString();m.author=v.getProperty("author",{}).toString();m.category=v.getProperty("category",{}).toString();m.description=v.getProperty("description",{}).toString();m.notes=v.getProperty("notes",{}).toString();m.tags=v.getProperty("tags",{}).toString();m.rating=jlimit(0,5,(int)v.getProperty("rating",0));return m;}

PresetLibrary::PresetLibrary(File base){if(base==File())base=ExternalPresetImport::defaultLibraryRoot().getParentDirectory();factoryRoot=base.getChildFile("Factory Packs");importedRoot=base.getChildFile("Packs");userRoot=base.getChildFile("User Packs");metadataRoot=base.getChildFile("Library Metadata");}

String PresetLibrary::inferCategory(String name){name=name.upToFirstOccurrenceOf(" -",false,false).toUpperCase();if(name=="BA")return "Bass";if(name=="LD")return "Lead";if(name=="PD")return "Pad";if(name=="KY")return "Keys";if(name=="PL")return "Pluck";if(name=="ARP")return "Arp";if(name=="CH")return "Chord";if(name=="FX")return "FX";return "Other";}

File PresetLibrary::metadataFile(const LibraryPreset& entry)const{if(entry.writable)return entry.file.getSiblingFile(entry.file.getFileName()+".metadata.json");return metadataRoot.getChildFile(String::toHexString(entry.id.hashCode64())+".json");}

PresetMetadata PresetLibrary::readMetadata(const File& file){PresetMetadata m;m.name=file.getFileNameWithoutExtension();m.category=inferCategory(m.name);if(file.hasFileExtension("ncsynth")){auto sidecar=file.getSiblingFile(file.getFileName()+".metadata.json");auto json=JSON::parse(sidecar.loadFileAsString());if(json.isObject())return PresetMetadata::fromJson(json);MemoryBlock bytes;if(file.getSize()<256*1024*1024&&file.loadFileAsData(bytes))if(auto xml=AudioProcessor::getXmlFromBinary(bytes.getData(),(int)bytes.getSize())){auto metadata=JSON::parse(xml->getStringAttribute("libraryMetadata"));if(metadata.isObject())return PresetMetadata::fromJson(metadata);}return m;}

 FileInputStream input(file);char magic[9];if(input.read(magic,9)!=9||std::memcmp(magic,"XferJson\0",9)!=0)return m;uint32 length=(uint32)input.readInt();input.readInt();if(length>4*1024*1024)return m;MemoryBlock buffer;if(input.readIntoMemoryBlock(buffer,(ssize_t)length)!=(int64)length)return m;auto metadata=JSON::parse(String::fromUTF8((const char*)buffer.getData(),(int)buffer.getSize()));if(!metadata.isObject())return m;m.name=metadata.getProperty("presetName",m.name).toString();m.author=metadata.getProperty("presetAuthor",{}).toString();m.description=metadata.getProperty("presetDescription",{}).toString();auto tags=metadata.getProperty("tags",{});if(auto* array=tags.getArray()){StringArray values;for(auto& value:*array)values.add(value.toString());m.tags=values.joinIntoString(", ");}return m;}

const LibraryPack* PresetLibrary::findPack(const String& id)const{for(auto& pack:packs)if(pack.id==id)return &pack;return nullptr;}

void PresetLibrary::refresh(){packs.clear();presets.clear();categories.clear();auto stored=metadataRoot.getChildFile("Categories.json");auto json=JSON::parse(stored.loadFileAsString());if(auto* array=json.getArray()){for(auto& item:*array)if(item.toString().isNotEmpty())categories.addIfNotAlreadyThere(item.toString());}else categories={"Bass","Lead","Pad","Keys","Pluck","Arp","Chord","FX","Drum","Other"};

 for(int kind:{0,1,2}){bool user=kind==0,native=kind!=1;File root=kind==0?userRoot:kind==1?importedRoot:factoryRoot;auto dirs=root.findChildFiles(File::findDirectories,false);dirs.sort();for(auto& folder:dirs){if(folder.isSymbolicLink())continue;LibraryPack pack;pack.folder=folder;pack.id=folder.getFullPathName();pack.name=folder.getFileName();pack.writable=user;pack.factory=kind==2;auto manifest=folder.getChildFile("NoCTRL-Pack.json");if(native&&!manifest.existsAsFile())continue;if(!native){auto files=folder.findChildFiles(File::findFiles,true,".SerumPack.json");if(files.size())manifest=files[0];}auto info=JSON::parse(manifest.loadFileAsString());if(info.isObject()){pack.name=info.getProperty("name",pack.name).toString();pack.author=info.getProperty("author",{}).toString();pack.description=info.getProperty("description",{}).toString();}

 auto files=folder.findChildFiles(File::findFiles,true,"*.ncsynth;*.SerumPreset");files.sort();for(auto& file:files){LibraryPreset entry;entry.file=file;entry.id=file.getFullPathName();entry.packId=pack.id;entry.packName=pack.name;entry.writable=user;entry.modified=file.getLastModificationTime();entry.metadata=readMetadata(file);auto json=JSON::parse(metadataFile(entry).loadFileAsString());if(json.isObject())entry.metadata=PresetMetadata::fromJson(json);if(entry.metadata.category.isNotEmpty())categories.addIfNotAlreadyThere(entry.metadata.category);presets.push_back(entry);++pack.count;}packs.push_back(pack);}}

}

Result PresetLibrary::removePack(const String& id){auto* entry=findPack(id);if(!entry||entry->factory)return Result::fail("Select an imported pack or one of your own packs.");auto folder=entry->folder;auto root=entry->writable?userRoot:importedRoot;if(folder.getParentDirectory()!=root||folder.isSymbolicLink()||!folder.isDirectory())return Result::fail("This pack folder cannot be removed.");if(!folder.moveToTrash())return Result::fail("Could not move this pack to the Recycle Bin. Check whether its files are in use.");refresh();return Result::ok();}

bool PresetLibrary::canManagePreset(const String& id)const{
 const LibraryPreset* selected=nullptr;for(auto& entry:presets)if(entry.id==id){selected=&entry;break;}if(!selected||selected->program>=0)return false;auto* pack=findPack(selected->packId);if(!pack||pack->factory||!selected->file.existsAsFile()||!selected->file.isAChildOf(pack->folder)||selected->file.isSymbolicLink())return false;
 auto root=pack->folder.getParentDirectory();if(root!=userRoot&&root!=importedRoot)return false;for(auto parent=selected->file.getParentDirectory();;parent=parent.getParentDirectory()){if(parent.isSymbolicLink())return false;if(parent==pack->folder)break;if(!parent.isAChildOf(pack->folder))return false;}return true;
}
bool PresetLibrary::canMovePreset(const String& id,const String& targetPack)const{auto* target=findPack(targetPack);if(!canManagePreset(id)||!target||target->factory||target->folder.isSymbolicLink()||!target->folder.isDirectory()||!target->folder.hasWriteAccess())return false;if(target->folder.getParentDirectory()!=userRoot&&target->folder.getParentDirectory()!=importedRoot)return false;for(auto& entry:presets)if(entry.id==id)return entry.packId!=targetPack;return false;}
Result PresetLibrary::movePreset(const String& id,const String& targetPack,File& moved,String newName){
 if(newName.isEmpty()?!canMovePreset(id,targetPack):!canManagePreset(id)||!findPack(targetPack)||findPack(targetPack)->factory)return Result::fail("Choose another writable pack as the destination.");LibraryPreset entry;for(auto& candidate:presets)if(candidate.id==id){entry=candidate;break;}auto target=*findPack(targetPack);MemoryBlock state;
 if(entry.file.hasFileExtension("SerumPreset")){auto temporary=std::make_unique<SynthProcessor>();String error;auto* sourcePack=findPack(entry.packId);if(!temporary->loadSerumPreset(entry.file,sourcePack->folder,error))return Result::fail(error);temporary->getStateInformation(state);}else if(entry.file.getSize()>256*1024*1024||!entry.file.loadFileAsData(state))return Result::fail("Could not read the source preset.");
 auto xml=AudioProcessor::getXmlFromBinary(state.getData(),(int)state.getSize());if(!xml||!noctrl::isSynthState(*xml))return Result::fail("The source preset is invalid.");
 newName=newName.isEmpty()?entry.file.getFileNameWithoutExtension():newName.trim();if(newName.isEmpty()||newName.length()>180||File::createLegalFileName(newName)!=newName||newName=="."||newName=="..")return Result::fail("Choose a valid preset name.");if(target.folder.getChildFile(newName+".ncsynth")==entry.file){moved=entry.file;return Result::ok();}moved=target.folder.getChildFile(newName+".ncsynth").getNonexistentSibling();int suffix=2;while(moved.exists()||moved.getSiblingFile(moved.getFileName()+".metadata.json").exists())moved=target.folder.getChildFile(newName+" ("+String(suffix++)+").ncsynth");auto metadata=entry.metadata;if(moved.getFileNameWithoutExtension()!=entry.file.getFileNameWithoutExtension())metadata.name=moved.getFileNameWithoutExtension();if(metadata.name.isEmpty())metadata.name=moved.getFileNameWithoutExtension();xml->setAttribute("currentPresetFile",moved.getFullPathName());xml->setAttribute("userPresetName",metadata.name);xml->setAttribute("libraryMetadata",JSON::toString(metadata.toJson(),true));MemoryBlock output;AudioProcessor::copyXmlToBinary(*xml,output);auto written=atomicWrite(moved,output);if(written.failed())return written;auto sidecar=moved.getSiblingFile(moved.getFileName()+".metadata.json");if(!sidecar.replaceWithText(JSON::toString(metadata.toJson(),true))){moved.deleteFile();return Result::fail("Could not write preset metadata. The original is unchanged.");}
 auto removed=deletePreset(id);if(removed.failed()){moved.deleteFile();sidecar.deleteFile();return removed;}refresh();return Result::ok();
}
Result PresetLibrary::renamePack(const String& id,String name,String& renamed){auto* pointer=findPack(id);name=name.trim();if(!pointer||pointer->factory||name.isEmpty()||name.startsWithChar('.')||name.length()>100||File::createLegalFileName(name)!=name)return Result::fail("Choose a valid pack name.");auto pack=*pointer;auto root=pack.folder.getParentDirectory();if(root!=userRoot&&root!=importedRoot||pack.folder.isSymbolicLink())return Result::fail("Invalid pack folder.");auto target=root.getChildFile(name);if(target==pack.folder){renamed=id;return Result::ok();}if(target.exists())return Result::fail("A pack with this name already exists.");auto entries=presets;auto manifest=pack.folder.getChildFile("NoCTRL-Pack.json");if(!manifest.existsAsFile()){auto matches=pack.folder.findChildFiles(File::findFiles,true,".SerumPack.json");if(matches.size())manifest=matches[0];}MemoryBlock manifestBefore;manifest.loadFileAsData(manifestBefore);auto info=JSON::parse(manifest.loadFileAsString());if(!info.isObject())info=var(new DynamicObject());info.getDynamicObject()->setProperty("name",name);if(!pack.folder.moveFileTo(target))return Result::fail("Could not rename pack.");auto newManifest=target.getChildFile(manifest.getRelativePathFrom(pack.folder));if(!newManifest.replaceWithText(JSON::toString(info,true))){target.moveFileTo(pack.folder);return Result::fail("Could not update pack metadata.");}
 struct Backup{File file;MemoryBlock bytes;bool existed;};std::vector<Backup> backups;for(auto& entry:entries)if(entry.packId==id&&!entry.writable){auto updated=entry;updated.file=target.getChildFile(entry.file.getRelativePathFrom(pack.folder));updated.id=updated.file.getFullPathName();auto next=metadataFile(updated);Backup backup{next,{},next.existsAsFile()};if(backup.existed)next.loadFileAsData(backup.bytes);backups.push_back(backup);if(!next.getParentDirectory().createDirectory().wasOk()||!next.replaceWithText(JSON::toString(entry.metadata.toJson(),true))){for(auto& b:backups){if(b.existed)b.file.replaceWithData(b.bytes.getData(),b.bytes.getSize());else b.file.deleteFile();}newManifest.replaceWithData(manifestBefore.getData(),manifestBefore.getSize());target.moveFileTo(pack.folder);return Result::fail("Could not preserve pack metadata; original restored.");}}
 renamed=target.getFullPathName();refresh();return Result::ok();}
Result PresetLibrary::editCategory(String oldName,String newName){newName=newName.trim();if(oldName.isEmpty()&&newName.isEmpty()||newName.length()>64||oldName.isNotEmpty()&&!categories.contains(oldName)||newName!=oldName&&newName.isNotEmpty()&&categories.contains(newName,true)&&!oldName.equalsIgnoreCase(newName))return Result::fail("Choose a new, valid category name.");struct Backup{File file;MemoryBlock bytes;bool existed;};std::vector<Backup> backups;auto backup=[&](File file){Backup b{file,{},file.existsAsFile()};if(b.existed&&!file.loadFileAsData(b.bytes))return false;backups.push_back(b);return true;};auto rollback=[&]{for(auto& b:backups){if(b.existed)b.file.replaceWithData(b.bytes.getData(),b.bytes.getSize());else b.file.deleteFile();}refresh();};auto updated=categories;if(oldName.isNotEmpty())updated.removeString(oldName);if(newName.isNotEmpty())updated.addIfNotAlreadyThere(newName);auto entries=presets;for(auto& entry:entries)if(oldName.isNotEmpty()&&entry.metadata.category==oldName){if(!backup(metadataFile(entry))||(entry.writable&&!backup(entry.file))){rollback();return Result::fail("Could not read category metadata.");}auto metadata=entry.metadata;metadata.category=newName;auto result=updateMetadata(entry,metadata);if(result.failed()){rollback();return result;}}Array<var> list;for(auto& category:updated)list.add(category);auto file=metadataRoot.getChildFile("Categories.json");file.getParentDirectory().createDirectory();TemporaryFile temporary(file);if(!temporary.getFile().replaceWithText(JSON::toString(var(list),true))||!temporary.overwriteTargetFileWithTemporary()){rollback();return Result::fail("Could not save categories.");}refresh();return Result::ok();}

Result PresetLibrary::deletePreset(const String& id){
 if(!canManagePreset(id))return Result::fail("Select a preset in an imported or own pack.");LibraryPreset entry;for(auto& candidate:presets)if(candidate.id==id){entry=candidate;break;}
 auto staging=metadataRoot.getChildFile(".deleted-"+Uuid().toString());if(staging.createDirectory().failed())return Result::fail("Could not prepare the Recycle Bin operation.");std::vector<std::pair<File,File>> transfers;
 auto transfer=[&](File source,String name){if(!source.existsAsFile())return true;auto target=staging.getChildFile(name);if(!source.moveFileTo(target))return false;transfers.push_back({source,target});return true;};
 auto rollback=[&]{for(auto it=transfers.rbegin();it!=transfers.rend();++it)it->second.moveFileTo(it->first);if(staging.getNumberOfChildFiles(File::findFiles)==0)staging.deleteFile();};
 auto sidecar=entry.file.getSiblingFile(entry.file.getFileName()+".metadata.json");auto global=metadataFile(entry);if(!transfer(entry.file,entry.file.getFileName())||!transfer(sidecar,sidecar.getFileName())||(global!=sidecar&&!transfer(global,"Library Metadata.json"))){rollback();return Result::fail("Could not move the preset. Its files were restored.");}
 if(!staging.moveToTrash()){rollback();return Result::fail("Could not move the preset to the Recycle Bin.");}refresh();return Result::ok();
}

Result PresetLibrary::atomicWrite(const File& file,const MemoryBlock& bytes){auto result=file.getParentDirectory().createDirectory();if(result.failed())return result;TemporaryFile temporary(file);{FileOutputStream stream(temporary.getFile());if(!stream.openedOk())return stream.getStatus();if(!stream.write(bytes.getData(),bytes.getSize()))return Result::fail("Could not write preset data");stream.flush();if(stream.getStatus().failed())return stream.getStatus();}return temporary.overwriteTargetFileWithTemporary()?Result::ok():Result::fail("Could not replace the destination file");}

Result PresetLibrary::createPack(String name,String author,String description,String& id){name=name.trim();if(name.isEmpty()||name=="."||name==".."||File::createLegalFileName(name)!=name||name.length()>100)return Result::fail("Choose a pack name without path separators or special file characters.");auto folder=userRoot.getChildFile(name);if(folder.exists())return Result::fail("A pack with that name already exists.");if(!folder.isAChildOf(userRoot))return Result::fail("Invalid pack folder.");auto result=folder.createDirectory();if(result.failed())return result;auto obj=std::make_unique<DynamicObject>();obj->setProperty("schema",1);obj->setProperty("name",name);obj->setProperty("author",author.trim());obj->setProperty("description",description);obj->setProperty("created",Time::getCurrentTime().toISO8601(true));String text=JSON::toString(var(obj.release()),true);if(!folder.getChildFile("NoCTRL-Pack.json").replaceWithText(text))return Result::fail("Could not save pack metadata.");id=folder.getFullPathName();refresh();return Result::ok();}

Result PresetLibrary::savePreset(const String& packId,const PresetMetadata& metadata,const MemoryBlock& state,File& saved){auto* pack=findPack(packId);if(!pack||!pack->writable||!pack->folder.isAChildOf(userRoot))return Result::fail("Select one of your own packs as the destination.");auto name=metadata.name.trim();if(name.isEmpty()||name.length()>180||File::createLegalFileName(name)!=name||name=="."||name=="..")return Result::fail("Choose a preset name without path separators or special file characters.");auto xml=AudioProcessor::getXmlFromBinary(state.getData(),(int)state.getSize());if(!xml||!noctrl::isSynthState(*xml))return Result::fail("This is not a valid NoCTRL synth state.");PresetMetadata finalMetadata=metadata;saved=pack->folder.getChildFile(name+".ncsynth").getNonexistentSibling();finalMetadata.name=saved.getFileNameWithoutExtension();xml->removeAttribute("factoryPreset");xml->setAttribute("currentPresetFile",saved.getFullPathName());xml->setAttribute("userPresetName",finalMetadata.name);xml->setAttribute("libraryMetadata",JSON::toString(finalMetadata.toJson(),true));MemoryBlock output;AudioProcessor::copyXmlToBinary(*xml,output);auto result=atomicWrite(saved,output);if(result.failed())return result;saved.getSiblingFile(saved.getFileName()+".metadata.json").replaceWithText(JSON::toString(finalMetadata.toJson(),true));refresh();return Result::ok();}

File PresetLibrary::currentPresetFile(SynthProcessor& p){String path=p.state.state.getProperty("currentPresetFile").toString();if(File::isAbsolutePath(path))return File(path);auto name=p.state.state.getProperty("userPresetName").toString();if(name.isEmpty())return {};auto files=ExternalPresetImport::defaultLibraryRoot().getParentDirectory().getChildFile("User Packs").findChildFiles(File::findFiles,true,"*.ncsynth");File match;for(auto& file:files)if(file.getFileNameWithoutExtension()==name){if(match!=File())return {};match=file;}return match;}

bool PresetLibrary::canOverwriteCurrent(SynthProcessor& p){auto file=currentPresetFile(p);return file.existsAsFile()&&file.hasFileExtension("ncsynth")&&file.hasWriteAccess();}

Result PresetLibrary::overwritePreset(const File& file,const PresetMetadata& metadata,const MemoryBlock& state){

 if(!file.existsAsFile()||!file.hasFileExtension("ncsynth")||!file.hasWriteAccess())return Result::fail(juce::String::fromUTF8("This preset cannot be overwritten. Create a new user preset first."));

 MemoryBlock existing;if(file.getSize()>256*1024*1024||!file.loadFileAsData(existing))return Result::fail("The preset could not be read.");auto previous=AudioProcessor::getXmlFromBinary(existing.getData(),(int)existing.getSize());if(!previous||!noctrl::isSynthState(*previous))return Result::fail("The destination file is not a compatible Nexum preset.");

 auto xml=AudioProcessor::getXmlFromBinary(state.getData(),(int)state.getSize());if(!xml||!noctrl::isSynthState(*xml))return Result::fail(juce::String::fromUTF8("Invalid preset state."));auto finalMetadata=metadata;if(finalMetadata.name.trim().isEmpty())finalMetadata.name=file.getFileNameWithoutExtension();xml->removeAttribute("factoryPreset");xml->setAttribute("currentPresetFile",file.getFullPathName());xml->setAttribute("userPresetName",finalMetadata.name);xml->setAttribute("libraryMetadata",JSON::toString(finalMetadata.toJson(),true));MemoryBlock output;AudioProcessor::copyXmlToBinary(*xml,output);auto result=atomicWrite(file,output);if(result.failed())return result;

 auto sidecar=file.getSiblingFile(file.getFileName()+".metadata.json");if(!sidecar.replaceWithText(JSON::toString(finalMetadata.toJson(),true)))return Result::fail("Preset saved; the metadata file could not be updated.");refresh();return Result::ok();

}

Result PresetLibrary::updateMetadata(const LibraryPreset& entry,const PresetMetadata& metadata){if(metadata.name.trim().isEmpty())return Result::fail("Preset name cannot be empty.");if(entry.writable&&entry.file.hasFileExtension("ncsynth")){MemoryBlock bytes;if(!entry.file.loadFileAsData(bytes))return Result::fail("Could not read preset.");auto xml=AudioProcessor::getXmlFromBinary(bytes.getData(),(int)bytes.getSize());if(!xml)return Result::fail("Preset state is invalid.");xml->setAttribute("userPresetName",metadata.name.trim());xml->setAttribute("libraryMetadata",JSON::toString(metadata.toJson(),true));MemoryBlock output;AudioProcessor::copyXmlToBinary(*xml,output);auto result=atomicWrite(entry.file,output);if(result.failed())return result;}auto sidecar=metadataFile(entry);auto result=sidecar.getParentDirectory().createDirectory();if(result.failed())return result;if(!sidecar.replaceWithText(JSON::toString(metadata.toJson(),true)))return Result::fail("Could not save metadata.");refresh();return Result::ok();}

}



